export type TemplateSectionFormat = 'paragraph' | 'list' | 'string';

export interface TemplateSection {
  title: string;
  instruction: string;
  format: TemplateSectionFormat;
  item_format?: string | null;
  example_item_format?: string | null;
}

/** Template metadata as listed in the UI. */
export interface TemplateInfo {
  id: string;
  name: string;
  description: string;
  /** User-created templates can be edited and deleted; built-in ones cannot. */
  is_custom: boolean;
}

/** Editable template content (no id: it is generated by the backend). */
export interface TemplateDraft {
  name: string;
  description: string;
  sections: TemplateSection[];
}

export interface TemplateFull extends TemplateInfo {
  sections: TemplateSection[];
}

export type TemplatesChange =
  | { type: 'saved'; template: TemplateInfo }
  | { type: 'deleted'; id: string };

/** Mirrors the limits enforced by the backend (summary/templates/types.rs). */
export const TEMPLATE_LIMITS = {
  name: 80,
  description: 300,
  sections: 30,
  sectionTitle: 100,
  instruction: 2000,
  itemFormat: 1000,
} as const;

export const DEFAULT_TEMPLATE_ID = 'standard_meeting';
